function flowPosition(t,index){return {x:Number.isFinite(t.flowX)?t.flowX:360+(index%3)*330,y:Number.isFinite(t.flowY)?t.flowY:70+Math.floor(index/3)*205};}
function renderFlowMap(){
 const projects=db.projects.filter(isLiveProject).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));if(!projects.length)return header('Flow Map','Conecte projeto, tarefas e dependências sem duplicar os objetos reais.',btn('Novo projeto','edit','primary','plus','data-kind="projects"'),'FLOW MAP')+`<section class="card">${empty('Ainda não há projeto ativo para mapear.','Crie um projeto e tarefas; o mapa usa os mesmos registros da operação.','edit','Novo projeto','folder','data-kind="projects"')}</section>`;
 if(!state.flowProject||!projects.some(p=>p.id===state.flowProject))state.flowProject=projects[0].id;const project=get('projects',state.flowProject),tasks=db.tasks.filter(t=>t.projectId===project.id&&t.status!=='cancelled');
 const nodes=tasks.map((t,i)=>({t,...flowPosition(t,i)})),positions=new Map(nodes.map(n=>[n.t.id,n]));const width=Math.max(1180,...nodes.map(n=>n.x+310)),height=Math.max(520,...nodes.map(n=>n.y+180));const root={x:35,y:Math.max(80,Math.min(height/2-70,260))};
 const edges=[];for(const n of nodes){const deps=(n.t.dependsOn||[]).filter(id=>positions.has(id));if(deps.length)for(const id of deps){const src=positions.get(id);edges.push({x1:src.x+260,y1:src.y+68,x2:n.x,y2:n.y+68});}else edges.push({x1:root.x+260,y1:root.y+68,x2:n.x,y2:n.y+68});}
 const z=state.flowZoom;
 return header('Flow Map','Uma visão dos mesmos projetos e tarefas, com dependências, bloqueios e responsáveis.',btn('Adicionar tarefa','edit','primary','plus',`data-kind="tasks" data-client-id="${project.clientId}" data-project-id="${project.id}"`),'FLOW MAP')+
 `<div class="flow-toolbar card"><label>Projeto <select data-action-change="flow-project">${options(Object.fromEntries(projects.map(p=>[p.id,`${p.title} · ${clientName(p.clientId)}`])),project.id)}</select></label><div class="flex">${btn('−','flow-zoom-out','small')}${badge(`${Math.round(z*100)}%`)}${btn('+','flow-zoom-in','small')}${btn('Centralizar','flow-center','small','target')}${btn('Abrir projeto','project-detail','small','folder',`data-id="${project.id}"`)}</div></div>`+
 `<div class="flow-legend"><span>${badge(PROJECT_STATUS[project.status],'purple')} ${esc(project.title)}</span><span>${tasks.length} nós de tarefa</span><span>${tasks.filter(taskIsBlocked).length} bloqueados</span><span>Arraste os nós para salvar sua posição</span></div>`+
 `<div class="flow-viewport card" id="flow-viewport"><div class="flow-scale" style="width:${width*z}px;height:${height*z}px"><div class="flow-surface" data-flow-surface style="width:${width}px;height:${height}px;transform:scale(${z})"><svg class="flow-edges" width="${width}" height="${height}" aria-hidden="true"><defs><marker id="flow-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 z"></path></marker></defs>${edges.map(e=>`<line x1="${e.x1}" y1="${e.y1}" x2="${e.x2}" y2="${e.y2}" marker-end="url(#flow-arrow)"></line>`).join('')}</svg><article class="flow-node flow-root" style="left:${root.x}px;top:${root.y}px"><div class="flow-node-top">${icon('folder')}<strong>${esc(project.title)}</strong></div><span>${esc(clientName(project.clientId))}</span><div class="flow-meta"><small>${esc(project.owner||'Sem responsável')}</small><small>${dateFmt(project.dueDate)}</small></div><div class="progress"><span style="width:${taskProgress(project).percent}%"></span></div></article>${nodes.map(({t,x,y})=>{const blocked=taskIsBlocked(t),prog=taskProgressValue(t);return `<article class="flow-node${blocked?' blocked':''}${t.status==='done'?' done':''}" data-flow-node="${t.id}" style="left:${x}px;top:${y}px" tabindex="0"><div class="flow-node-top"><span>${icon('checkSquare')}<strong>${esc(t.title)}</strong></span>${editBtn('tasks',t.id)}</div><div class="flow-status">${badge(TASK_STATUS[t.status],blocked?'red':t.status==='done'?'green':t.status==='approval'||t.status==='waiting_client'?'amber':'purple')}</div><div class="flow-meta"><small>${esc(t.owner||'Sem responsável')}</small><small class="${overdue(t.dueDate,taskClosed(t))?'negative':''}">${dateFmt(t.dueDate)}</small></div>${blocked?`<div class="flow-block">${esc(t.blockedReason||incompleteDependencies(t).map(d=>d.title).join(', ')||'Dependência pendente')}</div>`:''}<div class="progress"><span style="width:${prog}%"></span></div><small>${prog}% · ${esc(t.nextAction||'Sem próxima ação definida')}</small></article>`;}).join('')}</div></div></div><p class="list-note">O mapa não cria uma cópia das tarefas. Cada nó aponta para o registro real; mover o nó salva apenas suas coordenadas de visualização.</p>`;
}
