function nextProposalCode(){const year=today().slice(0,4),prefix=`PROP-${year}-`;let n=1;for(const p of db.proposals){if(p.code.startsWith(prefix)){const value=Number(p.code.slice(prefix.length));if(Number.isSafeInteger(value))n=Math.max(n,value+1);}}return prefix+String(n).padStart(3,'0');}
function safeUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
function safeLink(value,label='Abrir link'){const url=safeUrl(value);return url?`<a class="link-safe" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('link')}</a>`:esc(value||'—');}
