 if(kind==='clients'){r.tags=[...new Set(v('tags').split(',').map(t=>t.trim()).filter(Boolean))];if(r.website&&!safeUrl(r.website))throw Error('O site deve começar com http:// ou https:// e não pode conter usuário e senha.');}
