 if(kind==='tasks'){r.estimatedHours=parseDecimal(v('estimatedHours'),'Horas estimadas');r.spentHours=parseDecimal(v('spentHours'),'Horas realizadas');const progress=Number(v('progress'));if(!Number.isInteger(progress)||progress<0||progress>100)throw Error('O progresso deve ser um número inteiro entre 0 e 100.');r.progress=r.status==='done'?100:progress;r.participants=[...new Set(v('participants').split(/[,\n]/).map(x=>x.trim()).filter(Boolean))];r.dependsOn=form.elements.dependsOn?Array.from(form.elements.dependsOn.selectedOptions,o=>o.value):[];r.doneAt=r.status==='done'?(r.doneAt||today()):'';if(r.status!=='blocked'){r.blockedReason='';r.blockedBy='';r.blockedSince='';}else if(!r.blockedSince)r.blockedSince=today();if(r.projectId){const p=get('projects',r.projectId);r.clientId=p.clientId;}if(r.dealId&&get('deals',r.dealId)?.clientId!==r.clientId)r.dealId='';}
