function proposalDocument(p){const c=get('clients',p.clientId),s=db.settings;return `<article class="proposal-doc"><div class="doc-top"><div><div class="doc-label">Proposta comercial</div><div class="doc-brand">${esc(s.company)}</div><div>${esc(s.email)}${s.phone?' · '+esc(s.phone):''}</div>${s.document?`<div>Documento: ${esc(s.document)}</div>`:''}${s.city?`<div>${esc(s.city)}</div>`:''}</div><div><strong>${esc(p.code)}</strong><br>Emissão: ${new Date(p.createdAt).toLocaleDateString('pt-BR')}<br>Validade: ${dateFmt(p.validUntil)}</div></div><h1>${esc(p.title)}</h1><div class="doc-meta"><div><span class="doc-label">Preparada para</span><br><strong>${esc(c?.name||'')}</strong>${c?.contact?'<br>'+esc(c.contact):''}${c?.email?'<br>'+esc(c.email):''}${c?.document?'<br>Documento: '+esc(c.document):''}</div><div><span class="doc-label">Serviço</span><br>${SERVICES[p.service]}<br><span class="doc-label">Situação registrada internamente</span><br>${PROPOSAL_STATUS[p.status]}</div></div>${p.scope?`<h2>Escopo e entregáveis</h2><div class="pre-line">${esc(p.scope)}</div>`:''}<h2>Investimento</h2><table><thead><tr><th>Descrição</th><th class="right">Quantidade</th><th class="right">Valor unitário</th><th class="right">Total</th></tr></thead><tbody>${p.items.map(i=>`<tr><td class="pre-line">${esc(i.description)}</td><td class="right">${numFmt(i.quantity)}</td><td class="right nowrap">${money(i.unitCents)}</td><td class="right nowrap">${money(Math.round(i.quantity*i.unitCents))}</td></tr>`).join('')}</tbody></table>${p.discountCents?`<p class="right">Subtotal: ${money(proposalSubtotal(p))}<br>Desconto: ${money(p.discountCents)}</p>`:''}<div class="doc-total">Total: ${money(proposalTotal(p))}</div>${p.payment?`<h2>Condições de pagamento</h2><div class="pre-line">${esc(p.payment)}</div>`:''}${p.delivery?`<h2>Prazos e dependências</h2><div class="pre-line">${esc(p.delivery)}</div>`:''}${p.exclusions?`<h2>Fora do escopo</h2><div class="pre-line">${esc(p.exclusions)}</div>`:''}${p.notes?`<h2>Observações</h2><div class="pre-line">${esc(p.notes)}</div>`:''}<div class="doc-foot">${esc(s.company)} · ${esc(p.code)}<br>A indicação de status nesta proposta é um registro manual no CRM; não representa assinatura eletrônica ou comprovante de pagamento.</div></article>`;}
