function printProposal(id){const p=get('proposals',id);if(!p)return;$('#print-area').innerHTML=proposalDocument(p);const oldTitle=document.title;document.title=p.code+' - '+db.settings.company;const restore=()=>{document.title=oldTitle;};window.addEventListener('afterprint',restore,{once:true});window.print();setTimeout(restore,1500);}
async function toggleTask(id){const t=get('tasks',id);if(!t)return;const inDetail=$('#editor').open&&$('#editor').dataset.projectDetail===t.projectId&&!$('#record-form');const projectId=t.projectId;if(await commit(data=>{const task=data.tasks.find(x=>x.id===id);task.status=task.status==='done'?'todo':'done';task.doneAt=task.status==='done'?today():'';task.progress=task.status==='done'?100:Math.min(task.progress||0,99);task.updatedAt=isoNow();},t.status==='done'?'Tarefa reaberta.':'Tarefa concluída.')){render();if(inDetail){closeDialog(true);projectDetail(projectId);}}}
