async function savePayment(form){const id=form.dataset.id,date=form.elements.paidDate.value,method=form.elements.method.value;if(!validDate(date)||date>today()){showFormError(form,'Informe uma data válida que não esteja no futuro.');return;}if(await commit(data=>{const e=data.entries.find(e=>e.id===id);if(!e||e.status!=='open')throw Error('O lançamento já foi alterado.');e.status='paid';e.paidDate=date;e.method=method;e.updatedAt=isoNow();addActivity(data,e.clientId,`${e.type==='income'?'Recebimento':'Pagamento'} de ${money(e.valueCents)} registrado em ${dateFmt(date)}: ${e.description}.`);},'Liquidação registrada.')){dialogDirty=false;closeDialog(true);render();}}
function recurringPlan(month){if(!validMonth(month))return [];const lastDay=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0,12).getDate(),start=month+'-01',end=month+'-'+String(lastDay).padStart(2,'0');return db.contracts.filter(c=>c.status==='active'&&c.startDate<=end&&(!c.endDate||c.endDate>=start)&&!db.entries.some(e=>e.contractId===c.id&&e.competence===month)).map(c=>{let date=month+'-'+String(Math.min(c.dueDay,lastDay)).padStart(2,'0');if(date<c.startDate)date=c.startDate;if(c.endDate&&date>c.endDate)date=c.endDate;return {contract:c,dueDate:date};});}
function openRecurring(month=monthNow()){const plan=recurringPlan(month);showDialog('Gerar mensalidades',`<div class="notice"><div>Crie os lançamentos da competência selecionada. Recorrências pausadas ou encerradas e mensalidades já geradas são ignoradas, inclusive lançamentos cancelados. Nenhuma cobrança será enviada.</div></div><div class="form-grid">${field('recurringMonth','Competência a gerar','month',month,{required:true,full:true,extra:'data-action-change="recurring-month"'})}</div><div class="mt" id="recurring-preview">${recurringPreview(plan)}</div><p class="list-note">Sem proporcionalidade: o valor integral é gerado para cada mês com vigência. O vencimento é limitado ao mês e às datas de início/fim. Confira a prévia antes de confirmar.</p>`,btn('Cancelar','close-dialog')+btn(`Gerar ${plan.length} lançamento${plan.length===1?'':'s'}`,'confirm-recurring','primary','repeat',`data-month="${month}"${plan.length?'':' disabled'}`),{width:'800px'});}
function recurringPreview(plan){return plan.length?`<div class="csv-preview">${table(['Recorrência / cliente','Vencimento','Valor'],plan.map(({contract:c,dueDate})=>[`${esc(c.title)}<span class="secondary">${esc(clientName(c.clientId))}</span>`,dateFmt(dueDate),money(c.amountCents)]))}</div><div class="proposal-total mt-sm"><span>${plan.length} mensalidades</span><strong>${money(sum(plan,p=>p.contract.amountCents))}</strong></div>`:'<div class="empty" style="padding:25px"><h3>Nenhuma mensalidade nova a gerar.</h3><p style="margin-bottom:0">Verifique a competência, a vigência e o status dos contratos. Mensalidades existentes não são duplicadas.</p></div>';}
async function generateRecurring(month){const plan=recurringPlan(month);if(!plan.length){toast('Nenhuma mensalidade nova para gerar.');return;}if(await commit(data=>{for(const {contract:c,dueDate} of plan){if(data.entries.some(e=>e.contractId===c.id&&e.competence===month))continue;data.entries.push({...fresh('entries'),clientId:c.clientId,contractId:c.id,description:`${c.title} · ${monthFmt(month)}`,service:c.service,valueCents:c.amountCents,dueDate,competence:month,category:'Mensalidade'});}},`${plan.length} mensalidades geradas sem duplicação.`)){dialogDirty=false;closeDialog(true);state.month=month;nav('entries');}}
function calendarDay(date){const events=allEvents().filter(e=>e.date===date);showDialog('Agenda · '+dateFmt(date),events.length?`<ul class="plain-list">${events.map(e=>`<li><div><div class="tiny muted">${{task:'Tarefa',deal:'Retorno comercial',project:'Entrega de projeto',entry:'Vencimento'}[e.kind]}</div><button type="button" class="text-btn dark" data-action="${e.action}" data-kind="${e.type}" data-id="${e.id}">${esc(e.title)}</button></div>${ibtn('chevron',e.action,'Abrir registro',attrsId(e.type,e.id))}</li>`).join('')}</ul>`:empty('Um espaço livre na agenda.','Crie uma tarefa para este dia.','','','calendar'),btn('Fechar','close-dialog')+btn('Nova tarefa neste dia','edit','primary','plus',`data-kind="tasks" data-due-date="${date}"`),{width:'650px'});}
