function showAlerts(){const late=db.tasks.filter(t=>!taskClosed(t)&&t.dueDate<=today()).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),deals=db.deals.filter(d=>isOpenDeal(d)&&d.nextDate<=today()),entries=db.entries.filter(e=>e.status==='open'&&e.dueDate<today());showDialog('Sua atenção faz a diferença.',`<div class="detail-kpis"><div><small>Tarefas · até hoje</small><strong>${late.length}</strong></div><div><small>Retornos · até hoje</small><strong>${deals.length}</strong></div><div><small>Valores em atraso</small><strong>${entries.length}</strong></div></div><div class="detail-section"><h3>Tarefas prioritárias</h3>${late.length?late.slice(0,12).map(taskLine).join(''):'<p class="tiny muted">Nenhuma tarefa vencida ou para hoje.</p>'}</div><div class="detail-section"><h3>Retornos comerciais</h3>${deals.length?`<ul class="plain-list">${deals.slice(0,12).map(d=>`<li><button type="button" class="text-btn dark" data-action="edit" ${attrsId('deals',d.id)}>${esc(d.nextAction)} · ${esc(clientName(d.clientId))}</button><span class="tiny negative">${dateFmt(d.nextDate)}</span></li>`).join('')}</ul>`:'<p class="tiny muted">Nenhum retorno pendente para hoje.</p>'}</div><div class="detail-section"><h3>Financeiro em atraso</h3>${entries.length?`<ul class="plain-list">${entries.slice(0,12).map(e=>`<li><button type="button" class="text-btn dark" data-action="edit" ${attrsId('entries',e.id)}>${esc(e.description)}</button><span class="tiny">${e.type==='income'?'Receber':'Pagar'} ${money(e.valueCents)}</span></li>`).join('')}</ul>`:'<p class="tiny muted">Nenhum vencimento em atraso.</p>'}</div><p class="list-note">As pendências são verificadas ao abrir ou atualizar as telas. Não há notificações por e-mail, WhatsApp ou fora do navegador.</p>`,btn('Fechar','close-dialog'),{width:'770px'});}
