 clients:{headers:['empresa','contato','email','telefone','documento','segmento','origem','status','responsavel','tags','site','observacoes'],row:c=>[c.name,c.contact,c.email,c.phone,c.document,c.segment,c.source,CLIENT_STATUS[c.status],c.owner,c.tags.join(', '),c.website,c.notes]},
