 tasks:{headers:['Tarefa','Cliente','Projeto','Status','Prioridade','Responsável','Prazo','Concluída em','Horas estimadas','Horas realizadas','Observações'],row:t=>[t.title,t.clientId?clientName(t.clientId):'',t.projectId?projectName(t.projectId):'',TASK_STATUS[t.status],PRIORITIES[t.priority],t.owner,t.dueDate,t.doneAt,numFmt(t.estimatedHours),numFmt(t.spentHours),t.notes]},
