function parseCSV(text){text=text.replace(/^\uFEFF/,'');let quoted=false,semicolons=0,commas=0;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){i++;continue;}quoted=!quoted;}if(!quoted){if(ch===';')semicolons++;if(ch===',')commas++;if(ch==='\n'||ch==='\r')break;}}const delimiter=semicolons>=commas?';':',';let rows=[],row=[],field='',inQuotes=false,justClosed=false;for(let i=0;i<text.length;i++){const c=text[i];if(inQuotes){if(c==='"'){if(text[i+1]==='"'){field+='"';i++;}else{inQuotes=false;justClosed=true;}}else field+=c;}else if(c==='"'&&field===''){inQuotes=true;}else if(c===delimiter){row.push(field);field='';justClosed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';justClosed=false;}else{if(justClosed&&c.trim())throw Error('CSV inválido: caractere depois de uma célula entre aspas.');if(!justClosed)field+=c;}if(rows.length>MAX_RECORDS)throw Error(`Limite de ${MAX_RECORDS} linhas por arquivo.`);}if(inQuotes)throw Error('CSV inválido: há aspas sem fechamento.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;}
async function readClientCSV(file){if(!file)return;if(file.size>8*1024*1024){toast('O CSV deve ter até 8 MB.',true);return;}try{const rows=parseCSV(await file.text());if(rows.length<2)throw Error('O arquivo precisa ter cabeçalho e ao menos um cliente.');const aliases={empresa:'name',nomedaempresa:'name',nome:'name',cliente:'name',razaosocial:'name',contato:'contact',pessoadecontato:'contact',email:'email',emailcomercial:'email',telefone:'phone',whatsapp:'phone',celular:'phone',documento:'document',cnpj:'document',cpf:'document',segmento:'segment',origem:'source',status:'status',responsavel:'owner',tags:'tags',site:'website',website:'website',observacoes:'notes',notas:'notes'};const keys=rows[0].map(h=>aliases[normalize(h).replace(/[^a-z0-9]/g,'')]||'');if(!keys.includes('name'))throw Error('Não encontramos a coluna “empresa” ou “nome”. Baixe o modelo CSV em Configurações.');const seenEmail=new Set(db.clients.map(c=>normalize(c.email)).filter(Boolean)),seenName=new Set(db.clients.map(c=>normalize(c.name))),accepted=[],errors=[];let duplicates=0;for(let index=1;index<rows.length;index++){
 const cells=rows[index];if(cells.length!==keys.length){errors.push(`Linha ${index+1}: quantidade de colunas diferente do cabeçalho.`);continue;}
 const c=fresh('clients');keys.forEach((key,j)=>{if(key)c[key]=(cells[j]||'').trim();});if(!c.name||c.name.length>300){errors.push(`Linha ${index+1}: nome vazio ou longo demais.`);continue;}
 if(c.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)){errors.push(`Linha ${index+1}: e-mail inválido.`);continue;}
 if(c.website&&!safeUrl(c.website)){errors.push(`Linha ${index+1}: site sem http:// ou https:// válido.`);continue;}
 if(seenName.has(normalize(c.name))||(c.email&&seenEmail.has(normalize(c.email)))){duplicates++;continue;}
 const rawStatus=normalize(c.status);c.status=({lead:'lead','potencial cliente':'lead',potencial:'lead',active:'active',ativo:'active',inactive:'inactive',inativo:'inactive'})[rawStatus]||'lead';c.tags=Array.isArray(c.tags)?c.tags:String(c.tags).split(',').map(t=>t.trim()).filter(Boolean);if(Object.values(c).some(v=>typeof v==='string'&&v.length>6000)||c.tags.some(t=>t.length>100)||c.tags.length>30){errors.push(`Linha ${index+1}: um campo excede o tamanho permitido.`);continue;}seenName.add(normalize(c.name));if(c.email)seenEmail.add(normalize(c.email));accepted.push(c);
 }
 if(db.clients.length+accepted.length>MAX_RECORDS)throw Error(`A base ultrapassaria ${MAX_RECORDS} clientes.`);
 pendingClients=accepted;showDialog('Confira a importação de clientes',`<div class="detail-kpis"><div><small>Prontos para importar</small><strong>${accepted.length}</strong></div><div><small>Duplicados ignorados</small><strong>${duplicates}</strong></div><div><small>Linhas com erro</small><strong>${errors.length}</strong></div></div><div class="notice"><div>A importação adiciona clientes, sem alterar registros existentes. Duplicidade é verificada por e-mail ou nome da empresa. Status desconhecidos são tratados como “Potencial cliente”.</div></div>${accepted.length?`<div class="csv-preview">${table(['Empresa','Contato','E-mail'],accepted.slice(0,20).map(c=>[esc(c.name),esc(c.contact),esc(c.email)]))}</div><p class="list-note">Prévia de até 20 registros. Total a importar: ${accepted.length}.</p>`:''}${errors.length?`<div class="notice warning mt"><div>${errors.slice(0,12).map(esc).join('<br>')}${errors.length>12?'<br>Outras linhas com erro não estão listadas.':''}</div></div>`:''}`,btn('Cancelar','close-dialog')+btn(`Importar ${accepted.length} clientes`,'csv-confirm','primary','upload',accepted.length?'':'disabled'),{width:'830px'});
 }catch(e){toast('CSV não importado: '+e.message,true);}}
async function confirmClients(){if(!pendingClients?.length)return;const records=pendingClients;if(await commit(data=>{const names=new Set(data.clients.map(c=>normalize(c.name))),emails=new Set(data.clients.map(c=>normalize(c.email)).filter(Boolean));for(const c of records){if(names.has(normalize(c.name))||(c.email&&emails.has(normalize(c.email))))continue;data.clients.push(c);names.add(normalize(c.name));if(c.email)emails.add(normalize(c.email));}},'Clientes importados.')){pendingClients=null;dialogDirty=false;closeDialog(true);nav('clients');}}
