let flowDrag=null,flowPan=null;
document.addEventListener('pointerdown',event=>{const node=event.target.closest('[data-flow-node]');if(node&&!event.target.closest('button,a,input,select,textarea')){flowDrag={node,id:node.dataset.flowNode,x:event.clientX,y:event.clientY,left:parseFloat(node.style.left)||0,top:parseFloat(node.style.top)||0,moved:false};node.setPointerCapture?.(event.pointerId);event.preventDefault();return;}const viewport=event.target.closest('#flow-viewport');if(viewport&&event.target.closest('.flow-surface')&&!event.target.closest('.flow-node')){flowPan={viewport,x:event.clientX,y:event.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture?.(event.pointerId);viewport.classList.add('panning');}});
document.addEventListener('pointermove',event=>{if(flowDrag){const dx=(event.clientX-flowDrag.x)/state.flowZoom,dy=(event.clientY-flowDrag.y)/state.flowZoom;if(Math.abs(dx)+Math.abs(dy)>3)flowDrag.moved=true;flowDrag.node.style.left=`${Math.max(0,flowDrag.left+dx)}px`;flowDrag.node.style.top=`${Math.max(0,flowDrag.top+dy)}px`;event.preventDefault();}else if(flowPan){flowPan.viewport.scrollLeft=flowPan.left-(event.clientX-flowPan.x);flowPan.viewport.scrollTop=flowPan.top-(event.clientY-flowPan.y);event.preventDefault();}});
document.addEventListener('pointerup',async event=>{if(flowDrag){const drag=flowDrag;flowDrag=null;if(drag.moved){const left=Math.round(parseFloat(drag.node.style.left)||drag.left),top=Math.round(parseFloat(drag.node.style.top)||drag.top);await commit(data=>{const t=data.tasks.find(x=>x.id===drag.id);if(!t)throw Error('Tarefa não encontrada.');t.flowX=left;t.flowY=top;t.updatedAt=isoNow();},'Posição do nó salva.');render();}return;}if(flowPan){flowPan.viewport.classList.remove('panning');flowPan=null;}});
