document.addEventListener('drop',async event=>{const column=event.target.closest('[data-drop-kind]');if(!column||!dragItem||column.dataset.dropKind!==dragItem.kind)return;event.preventDefault();const {kind,id}=dragItem,stage=column.dataset.stage;dragItem=null;const r=get(kind,id);if(!r)return;if(kind==='deals'){
 if(r.stage===stage)return;if(stage==='lost'){openEditor('deals',id,{stage:'lost',closedAt:today()});return;}
 if(await commit(data=>{const deal=data.deals.find(x=>x.id===id);deal.stage=stage;deal.closedAt=['won','lost'].includes(stage)?today():'';deal.lossReason='';deal.updatedAt=isoNow();if(isOpenDeal(deal)&&(!deal.nextDate||!deal.nextAction)){deal.nextDate=today();deal.nextAction='Definir próximo contato';}if(stage==='won'){const c=data.clients.find(x=>x.id===deal.clientId);c.status='active';c.updatedAt=isoNow();}addActivity(data,deal.clientId,`Oportunidade “${deal.title}” movida para ${STAGES[stage]}.`);},'Etapa comercial atualizada.')){render();if(stage==='won'&&!db.projects.some(p=>p.dealId===id))showWonNext(get('deals',id));}
 }else if(kind==='tasks'&&r.status!==stage){if(stage==='blocked'){openEditor('tasks',id,{status:'blocked',blockedSince:today()});return;}if(await commit(data=>{const t=data.tasks.find(x=>x.id===id);t.status=stage;t.doneAt=stage==='done'?today():'';if(stage!=='blocked'){t.blockedReason='';t.blockedBy='';t.blockedSince='';}if(stage==='done')t.progress=100;t.updatedAt=isoNow();},'Tarefa atualizada.'))render();}});
