async function api(path,method='GET',body){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),25000);
 try{const res=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json',...(body!==undefined?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&csrfToken?{'X-CSRF-Token':csrfToken}:{})},body:body!==undefined?JSON.stringify(body):undefined,signal:controller.signal});
 let data;try{data=await res.json();}catch{throw Object.assign(Error('O servidor retornou uma resposta inválida. Confira a conexão antes de repetir.'),{uncertain:method!=='GET'});}
 window.dispatchEvent(new CustomEvent('nexo:network',{detail:{ok:res.status<500}}));
 if(!res.ok){const error=Error(data.message||(typeof data.detail==='string'?data.detail:'Não foi possível concluir a operação.'));error.status=res.status;error.details=data;throw error;}connectionOK=true;return data;
 }catch(e){if(!e.status){connectionOK=false;window.dispatchEvent(new CustomEvent('nexo:network',{detail:{ok:false}}));e.uncertain=method!=='GET';e.message='Sem confirmação do servidor. Os dados exibidos podem estar desatualizados. Use “Reconectar” antes de repetir a operação.';}throw e;}finally{clearTimeout(timeout);}}
function authScreen(mode='login',message=''){
 authMode=mode;sessionUser=null;csrfToken='';db=blankData();members=[];auditEvents=[];$('#editor').close();$('#search-dialog').close();$('#print-area').innerHTML='';dialogDirty=false;settingsDirty=false;document.body.dataset.role='anonymous';
 const setup=mode==='setup',reset=mode==='reset';
 $('#app').innerHTML=`<main class="auth-shell"><section class="auth-story"><div class="brand"><span class="brand-mark">n</span><div class="brand-name">nexo<span>CRM</span></div></div><div class="auth-story-main"><span class="auth-tag">MARKETING + PROGRAMAÇÃO</span><h1>Uma equipe.<br> Uma visão.<br> <em>Mais clareza.</em></h1><p>Conecte cada conversa à próxima entrega. Clientes, vendas e projetos no mesmo espaço de trabalho.</p><div class="auth-flow"><div><span>01</span>Conquiste</div><i>→</i><div><span>02</span>Entregue</div><i>→</i><div><span>03</span>Cresça</div></div></div><div class="auth-story-foot">Nexo CRM Mono · 3.0 <span>Seu negócio, conectado.</span></div></section><section class="auth-panel"><div class="auth-card"><div class="eyebrow">${setup?'PRIMEIRA INSTALAÇÃO':reset?'ACESSO À SUA CONTA':'SEU ESPAÇO DE TRABALHO'}</div><h2>${setup?'Vamos abrir seu espaço.':reset?'Defina sua senha.':'Bom ter você por aqui.'}</h2><p class="subtitle">${setup?'Crie a conta administradora da sua empresa. Não existe senha padrão.':reset?'O código é individual, vale por uma hora e pode ser usado uma única vez.':'Entre com a conta fornecida pelo administrador da sua empresa.'}</p><form id="auth-form"><div class="form-error" role="alert" style="${message?'display:block':''}">${esc(message)}</div><div class="auth-fields">${setup?field('token','Código de instalação','password','',{required:true,hint:'Na nuvem: variável NEXO_SETUP_TOKEN no painel da hospedagem. Local: terminal ou data/setup-token.txt. Não é sua senha.',extra:'autocomplete="off"'})+field('company','Nome da sua empresa','text','',{required:true})+field('name','Seu nome','text','',{required:true}):''}${reset?field('token','Código de ativação ou recuperação','password','',{required:true,extra:'autocomplete="off"'}):field('email','E-mail','email','',{required:true,extra:'autocomplete="username"'})}${field('password',setup||reset?'Crie uma senha':'Senha','password','',{required:true,extra:`autocomplete="${setup||reset?'new-password':'current-password'}" minlength="${setup||reset?12:1}" maxlength="128"`,hint:setup||reset?'De 12 a 128 caracteres. Prefira uma frase longa e exclusiva.':''})}${setup||reset?field('confirm','Confirme a senha','password','',{required:true,extra:'autocomplete="new-password"'}):''}</div><button class="btn primary auth-submit" type="submit">${setup?'Criar empresa e entrar':reset?'Salvar minha senha':'Entrar na minha conta'} ${icon('arrow')}</button></form><div class="auth-links">${setup?'<p>A primeira conta terá acesso administrativo. Outras contas poderão ser criadas em Equipe e acessos.</p>':reset?btn('Voltar ao login','auth-login','text-btn'):btn('Ativar conta / redefinir senha','auth-reset','text-btn')}</div><div class="auth-safety">${icon('shield')}<span>Acesso individual · Dados no servidor<br>Use apenas contas e dispositivos autorizados.</span></div></div><span class="auth-copyright"><button type="button" class="btn small" data-pwa-action="install">Instalar aplicativo</button></span></section></main>`;
 if(reset){const token=new URLSearchParams(location.hash.slice(1)).get('ativar');if(token){$('#auth-form [name=token]').value=token;history.replaceState(null,'',location.pathname);}}
}
async function submitAuth(form){const b=$('button[type=submit]',form);b.disabled=true;try{const v=k=>form.elements[k]?.value||'';if(authMode!=='login'&&v('password')!==v('confirm'))throw Error('As senhas não coincidem.');if(authMode==='reset'){await api('/api/password/reset','POST',{token:v('token'),password:v('password')});authScreen('login','Senha salva. Entre com seu e-mail e a nova senha.');return;}const packet=await api(authMode==='setup'?'/api/setup':'/api/login','POST',{email:v('email'),password:v('password'),...(authMode==='setup'?{name:v('name'),company:v('company'),token:v('token')}:{})});applyPacket(packet);state.page='dashboard';render();}catch(e){showFormError(form,e.message);}finally{if(b.isConnected)b.disabled=false;}}
async function startTeam(){try{if(new URLSearchParams(location.hash.slice(1)).has('ativar')){authScreen('reset');return;}const boot=await api('/api/bootstrap');if(boot.setupRequired){authScreen('setup');return;}try{applyPacket(await api('/api/session'));const initial=location.hash.slice(1);state.page=pageAllowed(initial)&&NAV.some(n=>n[0]===initial)?initial:'dashboard';render();}catch(e){authScreen('login',e.status===401?'':e.message);}}catch(e){authScreen('login',e.message);}}
async function sharedCommit(mutator,message='Alterações salvas no servidor.'){
 if(saving){toast('Uma gravação ainda está em andamento.',true);return false;}
 if(pendingTransaction){toast('Há um envio sem confirmação. Use Reconectar para conferir antes de alterar outros dados.',true);return false;}
 const before=clone(db),next=clone(db);let payload;
 try{mutator(next);const upserts=[],deletes=[];
 for(const kind of Object.keys(TYPES)){const old=new Map(before[kind].map(r=>[r.id,r])),after=new Map(next[kind].map(r=>[r.id,r]));for(const r of next[kind]){if(!old.has(r.id)||JSON.stringify(r)!==JSON.stringify(old.get(r.id)))upserts.push({kind,record:r,expectedRevision:old.get(r.id)?._rev||0});}for(const r of before[kind])if(!after.has(r.id))deletes.push({kind,id:r.id,expectedRevision:r._rev});}
 payload={requestId:uid(),upserts,deletes};if(JSON.stringify(before.settings)!==JSON.stringify(next.settings)){payload.settings=next.settings;payload.settingsRevision=before.meta.settingsRevision||0;}if(before.meta.demo!==next.meta.demo)payload.demo=next.meta.demo;
 if(!upserts.length&&!deletes.length&&!payload.settings&&payload.demo===undefined)return true;
 saving=true;document.body.classList.add('is-saving');pendingTransaction=payload;
 const packet=await api('/api/transactions','POST',payload);pendingTransaction=null;applyPacket(packet);if(message)toast(message);return true;
 }catch(e){if(e.status)pendingTransaction=null;if(e.status===409){state.externalChange=true;toast(e.message,true);const form=$('#record-form')||$('#settings-form');if(form)showFormError(form,e.message+' Feche o formulário após copiar o necessário e clique em Atualizar.');}else if(e.status===401){toast('Sessão expirada. Copie os textos não salvos e entre novamente pela opção Conta.',true);}else{toast(e.message,true);const form=$('#record-form')||$('#settings-form');if(form)showFormError(form,e.message);}return false;}finally{saving=false;document.body.classList.remove('is-saving');updateConnectionBadge();}}
function updateConnectionBadge(){const b=$('[data-action=sync]');if(b){b.classList.toggle('negative',!connectionOK||!!pendingTransaction);b.textContent=pendingTransaction?'Reconectar e conferir':connectionOK?'Atualizar':'Reconectar';}}
async function syncNow(force=false){
 if(!sessionUser||saving)return;
 if(pendingTransaction){try{saving=true;const packet=await api('/api/transactions','POST',pendingTransaction);pendingTransaction=null;applyPacket(packet);dialogDirty=false;closeDialog(true);render();toast('Envio conferido. A transação foi aplicada uma única vez.');}catch(e){if(e.status)pendingTransaction=null;toast(e.message,true);}finally{saving=false;}return;}
 if(force&&($('#editor').open||settingsDirty)){if(!window.confirm('Atualizar descarta campos ainda não salvos. Você já copiou o que precisa preservar?'))return;dialogDirty=false;settingsDirty=false;closeDialog(true);}
 if(!force&&($('#editor').open||settingsDirty||$('#search-dialog').open))return;
 try{const packet=await api('/api/state');const changed=packet.data.meta.revision!==db.meta.revision||packet.user.role!==sessionUser.role;if(changed||force){applyPacket(packet);render();if(force)toast('Dados conferidos com o servidor.');}}
 catch(e){if(e.status===401&&!$('#editor').open&&!settingsDirty)authScreen('login','Sua sessão terminou. Entre novamente.');else connectionOK=false;}updateConnectionBadge();}
function applyPermissions(root=document){
 document.body.dataset.role=sessionUser?.role||'anonymous';
 $$('[data-action]',root).forEach(b=>{const {action:a,kind:k,page:p}=b.dataset;let hide=false;
 if(a==='nav'&&p)hide=!pageAllowed(p);
 if(['edit','delete'].includes(a)&&k)hide=!canWrite(k);
 if(a==='csv-export'&&k)hide=!canRead(k);
 if(['entry-paid','generate-recurring','confirm-recurring'].includes(a))hide=!canWrite('entries');
 if(a==='task-toggle')hide=!canWrite('tasks');
 if(['backup','restore','demo','reset','reset-demo','restore-confirm'].includes(a))hide=!permissions.admin;
 if(['csv-import','csv-confirm'].includes(a))hide=!canWrite('clients');
 if(hide)b.hidden=true;
 });
 if(sessionUser?.role==='operations'){
 for(const name of ['budgetCents','dealId']){const el=$(`[name=${name}]`,root);if(el)el.closest('.field').hidden=true;}
 }
 if(!canRead('tasks'))$$('.detail-section',root).forEach(s=>{if($('h3',s)?.textContent.includes('Checklist'))s.hidden=true;});
 if(!canRead('entries'))$$('.detail-section',root).forEach(s=>{if($('h3',s)?.textContent.includes('Financeiro'))s.hidden=true;});
 if(!canRead('deals'))$$('.detail-section',root).forEach(s=>{const title=$('h3',s)?.textContent||'';if(title.includes('Oportunidade')||title.includes('Comercial')||title.includes('Proposta'))s.hidden=true;});
 updateConnectionBadge();
}
function renderTeamDashboard(){
 if(permissions.admin)return renderDashboard();
 const role=sessionUser.role,openTasks=db.tasks.filter(t=>!taskClosed(t)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),projects=db.projects.filter(isLiveProject),openDeals=db.deals.filter(isOpenDeal);
 let metrics='';
 if(role==='sales')metrics=kpi('Em negociação',money(sum(openDeals,'valueCents')),'Posição atual · sem anualização','funnel')+kpi('Oportunidades abertas',openDeals.length,'Acompanhe a próxima ação','target')+kpi('Propostas enviadas',db.proposals.filter(p=>p.status==='sent').length,'Aguardando decisão do cliente','doc')+kpi('Clientes na base',db.clients.length,'Relacionamentos centralizados','users');
 else if(role==='finance')metrics=kpi('Recebido no mês',money(cashFor(state.month,'income')),'Por data de recebimento','wallet')+kpi('Pago no mês',money(cashFor(state.month,'expense')),'Por data de pagamento','wallet')+kpi('Saldo do mês',money(cashFor(state.month,'income')-cashFor(state.month,'expense')),'Regime de caixa · não é lucro contábil','chart')+kpi('Recorrências ativas',db.contracts.filter(c=>c.status==='active').length,'Consulte vigência em Recorrências','repeat');
 else metrics=kpi('Projetos em aberto',projects.length,'Planejamento, execução ou aprovação','folder')+kpi('Tarefas em aberto',openTasks.length,'Próximas entregas da equipe','checkSquare')+kpi('Tarefas atrasadas',openTasks.filter(t=>overdue(t.dueDate)).length,'Revise prioridades e prazos','clock')+kpi('Clientes na base',db.clients.length,'Cadastro compartilhado para consulta','users');
 let content=role==='finance'?`<section class="card"><div class="card-head"><div><h2>Movimentação financeira</h2><p>Recebimentos e pagamentos efetivamente registrados · últimos seis meses</p></div></div>${cashChart(state.month)}<div class="card-footer">${btn('Abrir financeiro','nav','','wallet','data-page="entries"')}<input type="month" aria-label="Mês financeiro" data-action-change="month" value="${state.month}"></div></section>`:`<div class="grid cols-2"><section class="card"><div class="card-head"><div><h2>Próximas entregas</h2><p>Tarefas abertas por data de vencimento</p></div></div>${openTasks.length?openTasks.slice(0,7).map(taskLine).join(''):'<div class="mini-empty">Nenhuma tarefa pendente. Organize seu primeiro projeto.</div>'}</section><section class="card"><div class="card-head"><div><h2>Projetos em movimento</h2><p>Progresso calculado pelas tarefas concluídas</p></div></div>${projects.length?projects.slice(0,6).map(p=>`<div class="project-mini"><div class="between"><button class="text-btn dark" data-action="project-detail" data-id="${p.id}">${esc(p.title)}</button>${serviceBadge(p.service)}</div><p class="tiny muted mt-sm">${esc(clientName(p.clientId))} · ${dateFmt(p.dueDate)}</p><div class="progress mt-sm"><span style="width:${taskProgress(p).percent}%"></span></div></div>`).join(''):'<div class="mini-empty">Os próximos projetos aparecerão aqui.</div>'}</section></div>`;
 return header(`Olá, ${esc(sessionUser.name.split(' ')[0])}. Vamos avançar?`,'Seu espaço mostra apenas as áreas autorizadas para o seu perfil.',btn('Novo registro','quick-create','primary','plus'),ROLE_NAMES[role].toUpperCase())+`<div class="notice"><div>${icon('shield')} Perfil <strong>${ROLE_NAMES[role]}</strong> · As permissões também são verificadas no servidor. Campos de texto compartilhados devem conter apenas informações necessárias à equipe.</div></div><div class="kpi-grid">${metrics}</div>`+content;
}
function renderTeamSettings(){const s=db.settings;return header('Seu espaço, sob seu controle.','Identidade da empresa, portabilidade dos dados e manutenção.',btn('Ajuda e limites','help','','help'),'CONFIGURAÇÕES')+`<div class="settings-layout"><section class="card settings-block"><h2>Identidade da empresa</h2><p>Dados que também aparecem nas propostas.</p><form id="settings-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('company','Nome da empresa','text',s.company,{required:true})}${field('owner','Nome de apresentação','text',s.owner)}${field('email','E-mail comercial','email',s.email)}${field('phone','Telefone','tel',s.phone)}${field('document','CNPJ / documento','text',s.document)}${field('city','Cidade / UF','text',s.city)}<input type="hidden" name="brandColor" value="#111111"><div class="field"><label>Identidade visual</label><div class="mono-palette" aria-label="Paleta monocromática: branco, preto e cinzas"><i></i><i></i><i></i><i></i><span>Mono · Preto e branco</span></div></div>${field('monthlyGoalCents','Meta mensal de recebimentos (R$)','money',s.monthlyGoalCents)}${field('team','Responsáveis disponíveis, um por linha','textarea',s.team.join('\n'),{full:true,rows:5,hint:'Novas contas são adicionadas a esta lista. Editar nomes aqui não concede nem revoga acesso: gerencie as contas em Equipe e acessos.'})}</div><button type="submit" class="btn primary mt">${icon('check')}Salvar configurações</button></form></section><div class="grid" style="align-content:start"><section class="card settings-block"><h2>Dados da sua empresa</h2><p>O backup JSON preserva registros e vínculos de negócio. Não inclui contas, senhas nem auditoria. Proteja os arquivos baixados.</p><div class="flex wrap">${btn('Exportar backup','backup','primary','download')}${btn('Importar / restaurar','restore','','upload')}</div><div class="setting-item"><h3>Migrar da versão local</h3><p>No Nexo 1, exporte o backup JSON. Aqui, use Importar / restaurar e revise a prévia. A importação substitui os registros de negócio; não mescla bases. Interações antigas sem classificação ficam restritas ao administrador.</p></div><div class="setting-item"><h3>Importação de clientes</h3><p>CSV com prévia e proteção contra duplicidades por nome ou e-mail.</p><div class="flex wrap">${btn('Importar CSV','csv-import','small','upload')}${btn('Baixar modelo','csv-template','small','download')}</div></div></section><section class="card settings-block"><h2>Ambiente e recuperação</h2><p>Confira o banco e a política de backup. Em hospedagem gerenciada, valide a recuperação no painel do provedor; cópias temporárias do aplicativo não são backups permanentes.</p><div id="server-status">${serverStatus?statusHTML():'Use “Conferir ambiente” para consultar o servidor.'}</div><div class="flex wrap mt">${btn('Conferir ambiente','server-status','small','shield')}${btn('Ver auditoria','nav','small','list','data-page="audit"')}</div><div class="setting-item"><h3>Demonstração opcional</h3><p>Adiciona registros fictícios somente a uma base vazia. Todos os usuários autorizados verão os registros de demonstração.</p>${btn('Carregar demonstração','demo','small','eye')}</div><div class="setting-item"><h3 class="negative">Limpar registros de negócio</h3><p>Preserva contas e auditoria. Exige backup e confirmação explícita. Um arquivo de recuperação também é gravado no servidor.</p>${btn('Limpar base','reset','small danger','trash')}</div></section></div></div>`;}
function statusHTML(){return `<div class="status-grid"><div><small>Banco</small><strong>${esc(serverStatus.database)}</strong></div><div><small>Ambiente</small><strong>${serverStatus.production?'Produção':'Desenvolvimento local'}</strong></div><div><small>Contas ativas</small><strong>${serverStatus.activeUsers}</strong></div><div><small>${serverStatus.backupMode==='managed'?'Backup da hospedagem':'Último conjunto automático'}</small><strong style="font-size:12px">${serverStatus.backupMode==='managed'?'Conferir no painel do provedor':serverStatus.lastServerBackup?esc(new Date(serverStatus.lastServerBackup).toLocaleString('pt-BR')):'Nenhum registrado'}</strong></div></div>`;}
function renderMembers(){return header('Pessoas certas. Acessos definidos.','Contas individuais para trabalhar na mesma base da empresa.',btn('Adicionar pessoa','member-add','primary','plus'),'EQUIPE E ACESSOS')+`<div class="notice"><div>Não há cadastro público. A nova pessoa recebe um código individual de ativação com validade de uma hora. Compartilhe-o por um canal privado; o sistema não envia e-mails automaticamente.</div></div><div class="card">${members.length?table(['Pessoa','Perfil','Situação','Ações'],members.map(u=>[`<strong>${esc(u.name)}</strong><span class="secondary">${esc(u.email)}</span>`,badge(ROLE_NAMES[u.role],'purple'),badge(u.active?'Ativa':'Desativada',u.active?'green':'red'),`<div class="flex wrap">${btn('Editar','member-edit','small','edit',`data-id="${u.id}"`)}${u.active?btn('Novo acesso','member-reset','small','shield',`data-id="${u.id}"`):''}</div>`])):'<div class="mini-empty">Carregando contas ou nenhuma conta disponível. Use Atualizar contas.</div>'}</div><div class="mt">${btn('Atualizar contas','members-refresh','','repeat')}</div><div class="role-cards mt"><article class="card card-pad"><h3>Administrador</h3><p>Todos os módulos, contas, configurações, backups e auditoria.</p></article><article class="card card-pad"><h3>Comercial</h3><p>Clientes, vendas, propostas, projetos e tarefas. Sem acesso a recebimentos, despesas ou recorrências.</p></article><article class="card card-pad"><h3>Operação</h3><p>Consulta clientes e gerencia projetos, tarefas e interações compartilhadas. Valores de projeto e vínculos comerciais ficam ocultos.</p></article><article class="card card-pad"><h3>Financeiro</h3><p>Consulta clientes e projetos; gerencia lançamentos, recorrências e relatórios financeiros. Sem acesso ao funil ou às propostas.</p></article><article class="card card-pad"><h3>Cliente</h3><p>Portal isolado por cliente. Consulta projetos, entregas, conteúdo, campanhas e arquivos liberados; pode enviar solicitações, comentários, arquivos e aprovações do próprio cliente.</p></article></div>`;}
